81:impl Default for ConfigPlugin {
82:    fn default() -> Self {
83:        Self::new(DEFAULT_CONFIG_STORE_PATH)
84:    }
85:}
86:
87:impl ConfigPlugin {
88:    pub fn new(store_path: impl Into<PathBuf>) -> Self {
89:        Self {
90:            store_path: store_path.into(),
91:        }
92:    }
93:
94:    async fn load_store(&self) -> Result<ConfigStoreState> {
95:        match tokio::fs::read_to_string(&self.store_path).await {
96:            Ok(content) => {
97:                let parsed: ConfigStoreState =
98:                    serde_json::from_str(&content).context("invalid config store")?;
99:                Ok(parsed)
100:            }
101:            Err(_) => Ok(ConfigStoreState {
102:                configs: HashMap::new(),
103:            }),
104:        }
105:    }
106:
107:    async fn save_store(&self, state: &ConfigStoreState) -> Result<()> {
108:        if let Some(parent) = self.store_path.parent() {
109:            tokio::fs::create_dir_all(parent)
110:                .await
111:                .context("failed to create config store directory")?;
112:        }
113:
114:        let content = simd_json::to_string_pretty(state).context("serialize config store")?;
115:        tokio::fs::write(&self.store_path, content)
116:            .await
117:            .context("write config store")?;
118:        Ok(())
119:    }
120:}
