212:pub async fn dispatch_config_with_store(
213:    store: Arc<super::runtime_documents::RuntimeDocuments>,
214:    method: &str,
215:    args: &JsonValue,
216:) -> Result<JsonValue> {
217:    let document = store
218:        .read("config")
219:        .await?
220:        .map(|d| d.document)
221:        .unwrap_or_else(|| json!({"configs": {}}));
222:    let configs = document
223:        .get("configs")
224:        .and_then(JsonValue::as_object)
225:        .cloned()
